result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/summarize.py", "content": """"Streaming (itertools.groupby) vs materialized-list per-sensor mean summaries."""

import itertools
import random


def readings(sensors=1000, per_sensor=2000, seed=42):
    """Lazily yield (sensor_id, value) tuples, already sorted by sensor_id.

    Never materializes anything: one seeded RNG drives all values.
    """
    rng = random.Random(seed)
    for sensor_id in range(sensors):
        for _ in range(per_sensor):
            yield sensor_id, rng.gauss(50.0, 10.0)


def _means_by_sensor(stream):
    """Consume a sensor-sorted stream of (sensor_id, value), return {id: mean}."""
    means = {}
    for sensor_id, group in itertools.groupby(stream, key=lambda t: t[0]):
        total = 0.0
        count = 0
        for _, value in group:
            total += value
            count += 1
        means[sensor_id] = total / count
    return means


def summarize_stream(readings_iter):
    """Per-sensor means over a lazy iterator; O(1) readings held at any time."""
    return _means_by_sensor(readings_iter)


def summarize_list(readings_iter):
    """Materialize every reading into a list first, then compute per-sensor means."""
    data = list(readings_iter)
    return _means_by_sensor(iter(data))
