import math
import tracemalloc

import pytest

from summarize import readings, summarize_list, summarize_stream


@pytest.fixture(scope="session")
def stream_means():
    return summarize_stream(readings())


@pytest.fixture(scope="session")
def list_means():
    return summarize_list(readings())


def _peak_bytes(fn):
    gc.collect()
    tracemalloc.start()
    fn()
    _, peak = tracemalloc.get_traced_memory()
    tracemalloc.stop()
    return peak


def test_stream_peak_under_1mb():
    peak = _peak_bytes(lambda: summarize_stream(readings()))
    assert peak < 1_000_000, f"streaming peak {peak} bytes >= 1MB"


def test_list_peak_above_30mb():
    peak = _peak_bytes(lambda: summarize_list(readings()))
    assert peak > 30_000_000, f"list peak {peak} bytes <= 30MB"


def test_identical_means(stream_means, list_means):
    assert set(stream_means) == set(list_means)
    assert len(stream_means) == 1000
    for sid in stream_means:
        assert math.isclose(stream_means[sid], list_means[sid], rel_tol=1e-12)
